#include<stdio.h>
void f1(char *x, char *y) {
    char *t1;
    t1 = x;
    x = y;
    y = t1;
}

void f2(char **x, char **y) {
    char *t1;
    t1 = *x;
    *x = *y;
    *y = t1;
}

int main() {
    char *a = "ONE", *b = "TWO";
    f1(a, b);
    printf("%s %s ", a, b);
    f2(&a, &b);
    printf("%s %s", a, b);
    return 0;
}

#include<iostream.h>
using namespace std;
void swap(int &x, int &y)
{
    int temp=x;
    x=y;
    y=temp;
}
int main()
{
    int a=5, b=10;
    swap(a,b);
    swap(a,b);
    cout<<a<<" "<<b;
    return 0;
}

